```py
from typing import Any, Literal, Protocol, TypeIs, overload

class Source:
    @overload
    def read(self, key: Literal["value"]) -> object: ...
    @overload
    def read(self, key: str) -> Any: ...
    def read(self, key: str) -> Any:
        raise NotImplementedError

class Target(Protocol):
    def read(self, key: str) -> int: ...

def f(target: Target): ...

f(Source())
```

