### Prerequisites

- [x] I have written a descriptive issue title
- [x] I have searched existing issues to ensure the feature has not already been requested


### 🚀 Feature Proposal

Add native support for automatic, schema-driven deep population of all referenced paths without requiring explicit path specification. This would enable a "full populate" method (e.g., `Model.find().populateAll({ maxDepth: 3, exclude: ['sensitivePath'] })`) that inspects the schema for all `ref` fields, recursively populates them up to a configurable depth, and handles arrays/subdocs.

### Motivation

- Current support approaches require re-querying the document from the database after the transaction commit, which adds overhead and potential for race conditions if data changes meanwhile.
- Population paths are explicitly hardcoded ("posts", "comments", "author"), making the function brittle: Any schema changes (e.g., adding new refs like "tags" or deeper nesting) require manual updates to the code.
- No abstraction or automation: Lacks a generalized way to discover and populate all ref paths recursively based on the schema, leading to maintenance issues in complex, evolving models.
- Scalability concerns: For larger schemas with many levels of nesting or circular refs, maintaining these populate chains becomes error-prone and non-DRY (Don't Repeat Yourself).
- Inefficiency in transactions: Population isn't integrated with save/transaction ops, forcing separation of "save" and "populate" logic.

### Example

Reproducible example showing current problem space:

```javascript
const mongoose = require('mongoose');
const { Schema } = mongoose;

// 2. Define Models (minimal setup)
const Comment =
  mongoose.models.Comment ||
  mongoose.model(
    'Comment',
    new Schema({
      text: String,
      author: { type: Schema.Types.ObjectId, ref: 'User' },
    })
  );

const Post =
  mongoose.models.Post ||
  mongoose.model(
    'Post',
    new Schema({
      title: String,
      comments: [{ type: Schema.Types.ObjectId, ref: 'Comment' }],
    })
  );

const User =
  mongoose.models.User ||
  mongoose.model(
    'User',
    new Schema({
      name: String,
      posts: [{ type: Schema.Types.ObjectId, ref: 'Post' }],
    })
  );

async function buildFullPayload(userId) {
  return await User.findById(userId).populate({
    path: 'posts',
    populate: {
      path: 'comments',
      populate: { path: 'author' },
    },
  });
}

async function main() {
  try {
    console.log('--- Establishing Connection ---');
    await mongoose.connect('mongodb://localhost:27017/testdb');  // Adjust URI as needed

    // 3. Sandbox Setup: Clear existing data to prevent ID collisions or bloat
    console.log('--- Cleaning Sandbox ---');
    await Promise.all([User.deleteMany({}), Post.deleteMany({}), Comment.deleteMany({})]);

    const session = await mongoose.startSession();
    session.startTransaction();

    try {
      console.log('--- Running Transaction ---');
      const [user] = await User.create([{ name: 'Alice' }], { session });
      const [post] = await Post.create([{ title: 'My Post' }], { session });
      const [comment] = await Comment.create([{ text: 'Great post!', author: user._id }], { session });

      post.comments.push(comment._id);
      await post.save({ session });

      user.posts.push(post._id);
      await user.save({ session });

      await session.commitTransaction();
      console.log('Transaction Committed.');

      // 4. Analysis: Log evidence of staleness
      // First, show the in-memory user document post-commit (stale, with unpopulated refs as ObjectIDs)
      console.log('--- Evidence of Staleness ---');
      console.log('Stale User (in-memory post-commit):', JSON.stringify(user, null, 2));

      // Basic test
      const demoLogic = (doc, label) => {
        console.log(`--- ${label} Check ---`);
        // Try to access the first comment's author name
        const post = doc.posts?.[0];
        const firstComment = post?.comments?.[0];
        const authorName = firstComment?.author?.name;

        console.log(`Path: User -> Post -> Comment -> Author Name:`, authorName || '❌ NOT FOUND (Stale/Unpopulated)');
      };

      // 4.1. BEFORE population
      demoLogic(user, 'Stale Object');

      const fullPayload = await buildFullPayload(user._id);
      console.log('Full Populated Payload (after buildFullPayload):', JSON.stringify(fullPayload, null, 2));

      // 2. AFTER population
      demoLogic(fullPayload, 'Populated Object');

      // Log reasons why this version of buildFullPayload is unsatisfactory
      console.log('--- Reasons Why buildFullPayload is Unsatisfactory ---');
      console.log(
        '- Requires re-querying the document from the database after the transaction commit, which adds overhead and potential for race conditions if data changes meanwhile.'
      );
      console.log(
        '- Population paths are explicitly hardcoded ("posts", "comments", "author"), making the function brittle: Any schema changes (e.g., adding new refs like "tags" or deeper nesting) require manual updates to the code.'
      );
      console.log(
        '- No abstraction or automation: Lacks a generalized way to discover and populate all ref paths recursively based on the schema, leading to maintenance issues in complex, evolving models.'
      );
      console.log(
        "- Scalability concerns: For larger schemas with many levels of nesting or circular refs, maintaining these populate chains becomes error-prone and non-DRY (Don't Repeat Yourself)."
      );
      console.log('- Inefficiency in transactions: Population isn\'t integrated with save/transaction ops, forcing separation of "save" and "populate" logic.');
    } catch (err) {
      // Only abort if the transaction is still "In Progress"
      if (session.transaction.isActive) {
        await session.abortTransaction();
      }
      throw err;
    } finally {
      session.endSession();
    }

    // 5. Teardown: Drop collections to leave the DB as we found it
    console.log('--- Tearing Down Sandbox ---');
    await mongoose.connection.db.dropCollection('users');
    await mongoose.connection.db.dropCollection('posts');
    await mongoose.connection.db.dropCollection('comments');
    console.log('Teardown complete.');
  } catch (err) {
    console.error('Test Failed:', err);
  } finally {
    await mongoose.disconnect();
    console.log('Disconnected.');
  }
}

main();
```


