### Prerequisites

- [x] I have written a descriptive issue title
- [x] I have searched existing issues to ensure the bug has not already been reported


### Mongoose version

9.11.2

### Node.js version

26.10.0

### MongoDB server version

8.2.6 (mongodb-memory-server)

### Typescript version (if applicable)

_No response_

### Description

Since 6.8.3 `insertMany()` rebuilds each entry of `err.writeErrors` with a spread, `{ ...error.writeErrors[i], index: originalIndex }` ([lib/model.js#L3232](https://github.com/Automattic/mongoose/blob/9.11.2/lib/model.js#L3232)). The driver's `WriteError` keeps its data in `.err` and exposes `code`, `errmsg` and `index` as prototype getters, so the spread leaves `{ err, index }`: `writeErrors[i].code` is `undefined` and `getOperation()` is gone.

`bulkWrite()` with the same data returns real `WriteError`s, so `err.writeErrors.every(e => e.code === 11000)` works after `bulkWrite()` but not after `insertMany()`. The top-level `err.code` is fine.

Happy to send a PR: rebuild it with `new writeError.constructor({ ...writeError.err, index: originalIndex })`, which is what the driver does when it remaps indexes.


### Steps to Reproduce

`npm i mongoose@9.11.2 mongodb-memory-server`

```js
'use strict';
const mongoose = require('mongoose');
const { MongoMemoryServer } = require('mongodb-memory-server');

async function run() {
  const mms = await MongoMemoryServer.create();
  await mongoose.connect(mms.getUri());
  const Test = mongoose.model('Test', new mongoose.Schema({ name: { type: String, unique: true } }));
  await Test.init();
  await Test.create({ name: 'a' });

  const show = (label, err) => {
    const w = err.writeErrors[0];
    console.log(label, { ctor: w.constructor.name, code: w.code, index: w.index, errmsg: typeof w.errmsg, getOperation: typeof w.getOperation });
  };

  await Test.insertMany([{ name: 'b' }, { name: 'a' }], { ordered: false }).catch(err => show('insertMany', err));
  await Test.bulkWrite([
    { insertOne: { document: { name: 'c' } } },
    { insertOne: { document: { name: 'a' } } }
  ], { ordered: false }).catch(err => show('bulkWrite ', err));

  await mongoose.disconnect();
  await mms.stop();
}
run();
```

Output:

```
insertMany { ctor: 'Object', code: undefined, index: 1, errmsg: 'undefined', getOperation: 'undefined' }
bulkWrite  { ctor: 'WriteError', code: 11000, index: 1, errmsg: 'string', getOperation: 'function' }
```


### Expected Behavior

`writeErrors` entries are `WriteError` instances, the same as with `bulkWrite()`, with the remapped index.

