import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { transformSync } from '@babel/core';
import ts from 'typescript';
import { runInNewContext } from 'node:vm';

const require = createRequire(import.meta.url);
const input = readFileSync('input.ts', 'utf8');
const { code } = transformSync(input, {
  babelrc: false,
  configFile: false,
  parserOpts: { plugins: ['typescript'] }
});
console.log(code);
for (const source of [input, code]) {
  const js = ts.transpileModule(source, {
    compilerOptions: {
      target: ts.ScriptTarget.ES2022,
      module: ts.ModuleKind.CommonJS,
      verbatimModuleSyntax: true
    }
  }).outputText;
  try { runInNewContext(js, { console, require, exports: {} }); }
  catch (error) { console.log(error.code); }
}
```

In an empty directory, with Node 26.12.0:

```sh
npm install --save-exact @babel/core@8.0.7 typescript@6.0.3
node reproduce.mjs
```

After the printed TypeScript, the script logs `loaded` for the source and `MODULE_NOT_FOUND` for the reprinted code. Also reproduced with `@babel/core@7.29.7`.

### Possible cause

The [TSImportEqualsDeclaration printer](https://github.com/babel/babel/blob/v8.0.7/packages/babel-generator/src/generators/typescript.ts#L680-L694) prints `import`, the binding and the module reference without consulting `node.importKind`.

### Environment and verification

Verified 2026-10-19 on Node 26.12.0, macOS arm64, TypeScript 6.0.3:

| Core | Parser | Generator | Input AST | Reparsed output | Source loads | Output loads |
|---|---|---|---|---|---|---|
| 8.0.7 | 8.0.7 | 8.0.6 | type | value | none | ./only-types |
| 7.29.7 | 7.29.9 | 7.29.8 | type | value | none | ./only-types |

